#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

struct Zamowienie {
    string klient;
    int priorytet, czas;
};

int main() {
    ifstream plik("zamowienia.txt");
    vector<Zamowienie> zam;
    string k; int p, c;
    while (plik >> k >> p >> c) zam.push_back({k, p, c});

    sort(zam.begin(), zam.end(), [](const Zamowienie &a, const Zamowienie &b) {
        if (a.priorytet != b.priorytet) return a.priorytet < b.priorytet;
        return a.czas < b.czas;
    });

    cout << "a) Kolejnosc obslugi:" << endl;
    for (int i = 0; i < (int)zam.size(); i++) {
        cout << "   " << i+1 << ". " << zam[i].klient
             << " [P" << zam[i].priorytet << "] - " << zam[i].czas << " min" << endl;
    }

    cout << endl << "b) Czas zakonczenia:" << endl;
    int suma = 0;
    for (auto &z : zam) {
        suma += z.czas;
        cout << "   " << z.klient << ": " << suma << " min" << endl;
    }

    cout << endl << "c) Calkowity czas: " << suma << " min" << endl;
    return 0;
}
```

Weryfikacja:
Sortowanie: P1: Kaczmarek(5), Szymanski(7), Nowak(10); P2: Zielinski(12), Kowalski(15), Wojcik(18); P3: Majewski(8), Wisniewska(20)
Kumulatywny: 5, 5+7=12, 12+10=22, 22+12=34, 34+15=49, 49+18=67, 67+8=75, 75+20=95
Calkowity: 95 min
